#define LORA_RX 16
#define LORA_TX 17
#define M0 18
#define M1 19

HardwareSerial LoRa(2);

void setup() {
  Serial.begin(115200);

  pinMode(M0, OUTPUT);
  pinMode(M1, OUTPUT);

  // Normal transmission mode
  digitalWrite(M0, LOW);
  digitalWrite(M1, LOW);

  delay(500);

  LoRa.begin(9600, SERIAL_8N1, LORA_RX, LORA_TX);

  Serial.println("LORA TRANSMITTER READY");
}

void loop() {
  LoRa.println("HELLO FROM ESP32 #1");
  Serial.println("Message sent: HELLO FROM ESP32 #1");
  delay(2000);
}
